// The gate against real records: each preset written for a kind of record plays sixteen seconds in
// that style, and is measured exactly as the song corpus measured the separated stems of the
// user's own records (tests/record_features.hpp, the same features as song-corpus/scripts/
// features.py, pYIN tape wobble included). Every measure has to land inside the interquartile
// range of the stem the preset stands in for, for its group of records.
//
// The references (tests/record_reference.hpp) are numbers only, generated by
// tools/record_gate_profiles.py; no audio from the records is in the repository.
// Scenarios: features/record_gate.feature.
//
//   record_gate_tests [scenario-filter]   (prints every case's measures either way)

#include <cstdio>
#include <string>

#include "record_gate.hpp"
#include "spec.hpp"

using namespace record_gate;

SCENARIO(each_records_preset_sits_inside_the_records_quartiles) {
  GIVEN("each preset written for a kind of record, playing sixteen seconds of its phrase at 120 BPM");
  THEN("its centroid, 85% roll-off, share above 3 kHz, 100 ms crest, L/R correlation and pYIN tape wobble each land inside the quartiles of the stem it stands in for");
  std::printf("    %-30s %-9s %-6s %7s %7s %7s %6s %6s %7s\n", "preset", "records", "stem", "cent", "roll", "hf dB", "crest", "corr", "wobble");
  for (const Case& c : cases()) {
    const long index = preset_index(c.preset);
    const record::Reference* ref = reference(c.group, c.stem);
    CHECK(index >= 0, std::string("preset exists: ") + c.preset);
    CHECK(ref != nullptr, std::string("reference ") + c.group + " " + c.stem);
    if (index < 0 || !ref) continue;
    auto s = schrodr::Settings::defaults();
    schrodr::presets::apply(static_cast<size_t>(index), s.v.data());
    const Stereo audio = play(s, c.phrase);
    const record::Features f = record::measure_stem(audio.left, audio.right, kRate);
    const std::string failures = judge(f, *ref);
    std::printf("    %-30s %-9s %-6s %7.0f %7.0f %7.1f %6.1f %6.2f %7.1f %s\n", c.preset, c.group, c.stem, f.centroid_hz, f.rolloff85_hz,
                f.hf_share_db, f.crest100_db, f.corr, f.wobble_cents, failures.empty() ? "ok" : "FAIL");
    std::printf("    %-30s %-9s %-6s %7.0f %7.0f %7.1f %6.1f %6.2f %7.1f (records' medians)\n", "", "", "", ref->centroid_hz.median,
                ref->rolloff85_hz.median, ref->hf_share_db.median, ref->crest100_db.median, ref->corr.median, ref->wobble_cents.median);
    CHECK(failures.empty(), std::string(c.preset) + " as " + c.group + " " + c.stem + ": " + failures);
  }
}

int main(int argc, char** argv) { return spec::run(argc, argv); }
